<script setup lang="ts">
import Card from './ui/Card.vue';
import CardHeader from './ui/CardHeader.vue';
import CardTitle from './ui/CardTitle.vue';
import CardContent from './ui/CardContent.vue';
import Skeleton from './ui/Skeleton.vue';

const props = defineProps<{
  doc: string;
  loading: boolean;
}>();

function markdownToHtml(md: string): string {
  return md
    .replace(/^### (.*$)/gim, '<h3 class="text-lg font-semibold mt-3 mb-1">$1</h3>')
    .replace(/^## (.*$)/gim, '<h2 class="text-xl font-bold mt-4 mb-2">$1</h2>')
    .replace(/^# (.*$)/gim, '<h1 class="text-2xl font-extrabold mt-4 mb-2">$1</h1>')
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/g, '<em>$1</em>')
    .replace(/^\* (.*$)/gim, '<li>$1</li>')
    .replace(/^- (.*$)/gim, '<li>$1</li>')
    .replace(/(<li>.*<\/li>)/s, '<ul class="list-disc pl-5 space-y-1">$1</ul>')
    .replace(/\n/g, '<br>');
}
</script>

<template>
  <Card>
    <CardHeader>
      <CardTitle>📝 Kateto</CardTitle>
    </CardHeader>
    <CardContent>
      <div v-if="props.loading" class="space-y-2">
        <Skeleton class="h-4 w-3/4" />
        <Skeleton class="h-4 w-1/2" />
        <Skeleton class="h-4 w-5/6" />
        <Skeleton class="h-4 w-2/3" />
      </div>
      <div
        v-else-if="props.doc"
        class="prose prose-invert max-w-none text-sm text-slate-200"
        v-html="markdownToHtml(props.doc)"
      />
      <div v-else class="text-sm text-slate-500">
        Kateto Product Owner creara un documento a partir de la idea
      </div>
    </CardContent>
  </Card>
</template>
